import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';
import { getTursoClient } from '../_turso.js';
import { createRateLimiter, RATE_LIMITS } from '../middleware/rateLimiter.js';
import { readJson } from '../_core/body.js';
import { getReqEnv } from '../_core/env.js';

const getJwtSecret = (req) => getReqEnv(req, 'JWT_SECRET', 'your-secret-key-change-in-production');

const rateLimiter = createRateLimiter({ ...RATE_LIMITS.AUTH_REGISTER });
export default async function handler(req, res) {
  await rateLimiter(req, res, () => {});
  if (res.headersSent) return;
  try {
    if (req.method !== 'POST') {
      return res.status(405).json({ error: 'Method not allowed' });
    }

    const client = getTursoClient();

    // Create users table if not exists
    await client.execute(`
      CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
        email TEXT UNIQUE NOT NULL,
        username TEXT UNIQUE NOT NULL,
        passwordHash TEXT NOT NULL,
        createdAt TEXT DEFAULT (datetime('now')),
        updatedAt TEXT
      )
    `);

    const body = await readJson(req);
    const { email, username, password } = body;

    if (!email || !username || !password) {
      return res.status(400).json({ error: 'Email, username, and password required' });
    }

    // Check if email already exists
    const existing = await client.execute(
      'SELECT id FROM users WHERE email = ?',
      [email]
    );

    if (existing.rows && existing.rows.length > 0) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    // Check if username already exists
    const usernameExists = await client.execute(
      'SELECT id FROM users WHERE username = ?',
      [username]
    );

    if (usernameExists.rows && usernameExists.rows.length > 0) {
      return res.status(409).json({ error: 'Username already taken' });
    }

    // Hash password
    const passwordHash = await bcrypt.hash(password, 10);
    const userId = `user_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Default role for new users
    const role = 'member';

    // Insert user with role
    await client.execute(
      'INSERT INTO users (id, email, username, passwordHash, role) VALUES (?, ?, ?, ?, ?)',
      [userId, email, username, passwordHash, role]
    );

    // Generate token with role
    const token = jwt.sign(
      { userId, email, username, role },
      getJwtSecret(req),
      { expiresIn: '7d' }
    );

    return res.status(201).json({
      success: true,
      message: 'Registration successful',
      token,
      user: { id: userId, email, username }
    });

  } catch (error) {
    console.error('Register handler error:', error);
    if (res.headersSent) return;
    res.status(500).json({ error: error.message || 'Registration failed' });
  }
}
