import crypto from 'node:crypto';
import bcrypt from 'bcryptjs';
import { getTursoClient } from '../_turso.js';
import { getReqEnv } from '../_core/env.js';
import { sendMail } from '../_mailer.js';
import { readJson } from '../_core/body.js';
import { randomHex } from '../_core/crypto.js';

// SMTP settings are shared with api/bands/index.js; both naming styles are
// accepted so a single provider config works on Vercel and Cloudflare.
const smtpConfig = (req) => ({
  host: getReqEnv(req, 'SMTP_HOST') || getReqEnv(req, 'EMAIL_HOST'),
  port: getReqEnv(req, 'SMTP_PORT') || getReqEnv(req, 'EMAIL_PORT'),
  user: getReqEnv(req, 'SMTP_USER') || getReqEnv(req, 'EMAIL_USER'),
  pass: getReqEnv(req, 'SMTP_PASS') || getReqEnv(req, 'EMAIL_PASSWORD'),
  appUrl: getReqEnv(req, 'APP_URL', 'http://localhost:5173'),
});

/**
 * POST /api/auth/forgot-password
 * Request password reset token via email
 */
import { createRateLimiter, RATE_LIMITS } from '../middleware/rateLimiter.js';
const rateLimiter = createRateLimiter({ ...RATE_LIMITS.AUTH_FORGOT });
export default async function handler(req, res) {
  await rateLimiter(req, res, () => {});
  if (res.headersSent) return;
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  try {
    const { email } = await readJson(req);

    if (!email) {
      return res.status(400).json({ error: 'Email is required' });
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    const client = getTursoClient();

    // Find user by email
    const userResult = await client.execute(
      'SELECT id, username FROM users WHERE email = ?',
      [email]
    );

    // Always return success message (security: don't reveal if email exists)
    if (!userResult.rows || userResult.rows.length === 0) {
      // Log attempt but don't reveal account doesn't exist
      return res.status(200).json({
        message: 'If an account exists with this email, a reset link has been sent'
      });
    }

    const userId = userResult.rows[0].id;

    // Generate reset token
    const resetToken = randomHex(32);
    const tokenHash = crypto.createHash('sha256').update(resetToken).digest('hex');
    const expiresAt = new Date(Date.now() + 1 * 60 * 60 * 1000); // 1 hour

    // Store token in database
    await client.execute(
      `INSERT INTO password_reset_tokens
       (userId, tokenHash, expiresAt, createdAt)
       VALUES (?, ?, ?, CURRENT_TIMESTAMP)`,
      [userId, tokenHash, expiresAt.toISOString()]
    );

    // Send email with reset link
    const smtp = smtpConfig(req);
    const resetLink = `${smtp.appUrl}/reset-password?token=${resetToken}&email=${encodeURIComponent(email)}`;

    try {
      await sendMail(req, {
        from: smtp.user,
        to: email,
        subject: 'Ruang Performer - Reset Your Password',
        html: `
          <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
            <h2 style="color: #3b82f6;">Password Reset Request</h2>
            <p>Hi ${userResult.rows[0].username},</p>
            <p>We received a request to reset your password. Click the link below to create a new password:</p>
            <p style="margin: 30px 0;">
              <a href="${resetLink}" 
                 style="background-color: #3b82f6; color: white; padding: 12px 24px; 
                        text-decoration: none; border-radius: 6px; display: inline-block;">
                Reset Password
              </a>
            </p>
            <p>Or copy and paste this link:</p>
            <p style="word-break: break-all; color: #666;">${resetLink}</p>
            <p style="color: #999; font-size: 12px;">This link expires in 1 hour.</p>
            <p style="color: #999; font-size: 12px;">
              If you didn't request this reset, you can safely ignore this email.
            </p>
          </div>
        `,
        text: `
          Password Reset Request

          Hi ${userResult.rows[0].username},

          Click the link below to reset your password:
          ${resetLink}

          This link expires in 1 hour.

          If you didn't request this reset, you can safely ignore this email.
        `
      });
    } catch (emailError) {
      console.error('Email send error:', emailError);
      return res.status(500).json({ error: 'Failed to send reset email' });
    }

    return res.status(200).json({
      message: 'If an account exists with this email, a reset link has been sent'
    });
  } catch (error) {
    console.error('Forgot password error:', error);
    if (res.headersSent) return;
    return res.status(500).json({ error: 'Failed to process password reset request' });
  }
}
